using System;
using System.Collections.Generic;
using UnityEngine;
using Entities.Players.Data;
using Entities.Enemies.Helpers;

[Serializable]
public struct EnemyAction
{
    public EnemyIntent intent;
    public int value;
}

public enum EnemyIntent
{
    Attack,
    Block,
    Heal,
    Buff
}

[Serializable]
public class IntentIconMapping
{
    [Header("Intent Icons")]
    [Tooltip("Icon shown when enemy intends to attack")]
    public Sprite attackIcon;

    [Tooltip("Icon shown when enemy intends to block/defend")]
    public Sprite blockIcon;

    [Tooltip("Icon shown when enemy intends to heal")]
    public Sprite healIcon;

    [Tooltip("Icon shown when enemy intends to buff")]
    public Sprite buffIcon;

    /// <summary>
    /// Get the appropriate icon sprite for the given intent.
    /// </summary>
    public Sprite GetIconForIntent(EnemyIntent intent)
    {
        return intent switch
        {
            EnemyIntent.Attack => attackIcon,
            EnemyIntent.Block => blockIcon,
            EnemyIntent.Heal => healIcon,
            EnemyIntent.Buff => buffIcon,
            _ => null
        };
    }
}

[Serializable]
public class EnemyData : EntityData
{
    [Header("Core Stats")]
    public int attackPower;           // Base attack power for intents
    public int defensePower;          // Optional, if you have defensive actions

    [Header("Intent System")]
    public EnemyIntent currentIntent; // What the enemy plans to do this turn
    public IntentIconMapping intentIcons; // Sprite icons for each intent type
    public string intentText;         // Text like "Attack" or "Buff Self"
    public int intentValue;           // How much damage or block that intent will do

    /// <summary>
    /// Gets the sprite icon for the current intent.
    /// </summary>
    public Sprite GetCurrentIntentIcon()
    {
        if (intentIcons == null)
        {
            Debug.LogWarning($"[EnemyData] {enemyName} has no intent icons assigned!");
            return null;
        }
        return intentIcons.GetIconForIntent(currentIntent);
    }

    [Header("Behavior")]
    public List<EnemyAction> actionPattern; // Optional list of possible actions

    [Header("Metadata")]
    public int enemyID;
    public string enemyName;
    public Sprite artwork;                  // Optional portrait or sprite
    public AudioClip attackSFX;             // Optional sound for attack

    [Header("Animator (Optional)")]
    public RuntimeAnimatorController animatorController; // If set, animator-driven states are used

    [Header("Sprite Animations (Lightweight alternative to AnimationClips)")]
    public SpriteAnimation idleAnim;
    public SpriteAnimation attackAnim;
    public SpriteAnimation hurtAnim;
    public SpriteAnimation deathAnim;

    [Header("Visual Adjustments")]
    public Vector3 positionOffset = Vector3.zero;
    public Vector3 scaleOffset = Vector3.one;

    // -------------------------------------------------------
    // Initialization
    // -------------------------------------------------------
    public void Initialize(string name, int maxHealth, int atk, int def)
    {
        enemyName = name;
        attackPower = atk;
        defensePower = def;

        // Call base EntityData initialization
        base.Initialize(name, maxHealth);

        actionPattern = new List<EnemyAction>();
    }

    // -------------------------------------------------------
    // Enemy chooses what to do next - Intelligent AI System
    // -------------------------------------------------------
    public void DecideNextIntent()
    {
        if (actionPattern == null || actionPattern.Count == 0)
        {
            // Default: simple attack
            currentIntent = EnemyIntent.Attack;
            intentValue = attackPower;
            intentText = "Attack";
            return;
        }

        // Use intelligent AI to decide best move based on current situation
        EnemyAction chosenAction = ChooseStrategicAction();
        currentIntent = chosenAction.intent;
        intentValue = chosenAction.value;
        intentText = chosenAction.intent.ToString();
    }

    /// <summary>
    /// Intelligent AI system that chooses the best action based on enemy's current stats and situation.
    /// </summary>
    private EnemyAction ChooseStrategicAction()
    {
        // Calculate health percentage
        float healthPercent = currentHealth / (float)maxHealth;

        // Separate actions by type for strategic selection
        List<EnemyAction> attackActions = new List<EnemyAction>();
        List<EnemyAction> blockActions = new List<EnemyAction>();
        List<EnemyAction> healActions = new List<EnemyAction>();
        List<EnemyAction> buffActions = new List<EnemyAction>();

        foreach (var action in actionPattern)
        {
            switch (action.intent)
            {
                case EnemyIntent.Attack:
                    attackActions.Add(action);
                    break;
                case EnemyIntent.Block:
                    blockActions.Add(action);
                    break;
                case EnemyIntent.Heal:
                    healActions.Add(action);
                    break;
                case EnemyIntent.Buff:
                    buffActions.Add(action);
                    break;
            }
        }

        // Calculate average block value to set "low block" threshold
        int averageBlockValue = 0;
        if (blockActions.Count > 0)
        {
            int totalBlockValue = 0;
            foreach (var blockAction in blockActions)
            {
                totalBlockValue += blockAction.value;
            }
            averageBlockValue = totalBlockValue / blockActions.Count;
        }

        // Define block thresholds based on available block actions
        int lowBlockThreshold = averageBlockValue / 2; // Half of average block is "low"
        int criticalBlockThreshold = Mathf.Max(3, averageBlockValue / 4); // Very low block
        bool hasLowBlock = block > 0 && block <= lowBlockThreshold;
        bool hasCriticalBlock = block > 0 && block <= criticalBlockThreshold;
        bool hasNoBlock = block == 0;
        bool hasGoodBlock = block > lowBlockThreshold;

        // AI Decision Tree based on stats and situation

        // CRITICAL HEALTH (< 20%) - Prioritize survival
        if (healthPercent < 0.2f)
        {
            // First priority: Heal if available
            if (healActions.Count > 0)
            {
                Debug.Log($"[AI] {enemyName} is critical ({healthPercent:P0}) - choosing HEAL");
                return GetRandomAction(healActions);
            }
            // Second priority: Block to survive (even if we have some block)
            if (blockActions.Count > 0 && (hasNoBlock || hasCriticalBlock))
            {
                Debug.Log($"[AI] {enemyName} is critical ({healthPercent:P0}) with low/no block ({block}) - choosing BLOCK");
                return GetRandomAction(blockActions);
            }
        }

        // LOW HEALTH (20% - 50%) - Defensive play
        if (healthPercent < 0.5f)
        {
            // High priority: Heal if available (70% chance)
            if (healActions.Count > 0 && UnityEngine.Random.value < 0.7f)
            {
                Debug.Log($"[AI] {enemyName} is low health ({healthPercent:P0}) - choosing HEAL");
                return GetRandomAction(healActions);
            }

            // Maintain block coverage - refresh if low or none
            if (blockActions.Count > 0 && (hasNoBlock || hasLowBlock))
            {
                // 70% chance to refresh block when vulnerable at low health
                if (UnityEngine.Random.value < 0.7f)
                {
                    Debug.Log($"[AI] {enemyName} is low health ({healthPercent:P0}) with low block ({block}) - refreshing BLOCK");
                    return GetRandomAction(blockActions);
                }
            }
        }

        // BLOCK MAINTENANCE (any health) - Keep defensive coverage
        if (hasNoBlock && blockActions.Count > 0)
        {
            // 50% chance to block when completely unprotected
            if (UnityEngine.Random.value < 0.5f)
            {
                Debug.Log($"[AI] {enemyName} has no block - choosing BLOCK for protection");
                return GetRandomAction(blockActions);
            }
        }
        else if (hasCriticalBlock && blockActions.Count > 0)
        {
            // 40% chance to refresh when block is critically low
            if (UnityEngine.Random.value < 0.4f)
            {
                Debug.Log($"[AI] {enemyName} has critically low block ({block}) - refreshing BLOCK");
                return GetRandomAction(blockActions);
            }
        }
        else if (hasLowBlock && blockActions.Count > 0)
        {
            // 25% chance to maintain when block is just low
            if (UnityEngine.Random.value < 0.25f)
            {
                Debug.Log($"[AI] {enemyName} has low block ({block}) - maintaining BLOCK");
                return GetRandomAction(blockActions);
            }
        }

        // FULL HEALTH with GOOD BLOCK - Can afford to buff
        if (healthPercent > 0.8f && hasGoodBlock && buffActions.Count > 0)
        {
            // 30% chance to buff when safe
            if (UnityEngine.Random.value < 0.3f)
            {
                Debug.Log($"[AI] {enemyName} is healthy ({healthPercent:P0}) with good block ({block}) - choosing BUFF");
                return GetRandomAction(buffActions);
            }
        }

        // DEFAULT - Attack (aggressive AI)
        if (attackActions.Count > 0)
        {
            Debug.Log($"[AI] {enemyName} choosing ATTACK (HP: {healthPercent:P0}, Block: {block})");
            return GetRandomAction(attackActions);
        }

        // FALLBACK - Return any random action if attack not available
        Debug.LogWarning($"[AI] {enemyName} has no attack actions - picking random");
        return actionPattern[UnityEngine.Random.Range(0, actionPattern.Count)];
    }

    /// <summary>
    /// Helper method to get a random action from a list
    /// </summary>
    private EnemyAction GetRandomAction(List<EnemyAction> actions)
    {
        if (actions == null || actions.Count == 0)
        {
            Debug.LogError("[AI] GetRandomAction called with empty list!");
            return actionPattern[0]; // Fallback
        }
        return actions[UnityEngine.Random.Range(0, actions.Count)];
    }

    // -------------------------------------------------------
    // Execute current intent
    // -------------------------------------------------------
    public void ExecuteIntent(PlayerData player)
    {
        if (player == null) return;

        switch (currentIntent)
        {
            case EnemyIntent.Attack:
                player.TakeDamage(intentValue);
                break;

            case EnemyIntent.Block:
                GainBlock(intentValue);  // Now calls inherited method
                break;

            case EnemyIntent.Heal:
                Heal(intentValue);  // Now calls inherited method
                break;

            case EnemyIntent.Buff:
                ApplyStatus("Strength", intentValue);  // Now calls inherited method
                break;
        }
    }

    public bool IsAlive() => isAlive;  // Now uses inherited field
}

using System;
using System.Collections.Generic;
using UnityEngine;
using Entities.Players.Data;
using Entities.Enemies.Helpers;

[Serializable]
public struct EnemyAction
{
    public EnemyIntent intent;
    public int value;

    [Tooltip("Optional custom name for this action (e.g., 'Crushing Blow' instead of 'Attack'). Leave empty to use default.")]
    public string customName;
}

public enum EnemyIntent
{
    Attack,
    Block,
    Heal,
    Buff
}

[Serializable]
public class IntentIconMapping
{
    [Header("Intent Icons")]
    [Tooltip("Icon shown when enemy intends to attack")]
    public Sprite attackIcon;

    [Tooltip("Icon shown when enemy intends to block/defend")]
    public Sprite blockIcon;

    [Tooltip("Icon shown when enemy intends to heal")]
    public Sprite healIcon;

    [Tooltip("Icon shown when enemy intends to buff")]
    public Sprite buffIcon;

    /// <summary>
    /// Get the appropriate icon sprite for the given intent.
    /// </summary>
    public Sprite GetIconForIntent(EnemyIntent intent)
    {
        return intent switch
        {
            EnemyIntent.Attack => attackIcon,
            EnemyIntent.Block => blockIcon,
            EnemyIntent.Heal => healIcon,
            EnemyIntent.Buff => buffIcon,
            _ => null
        };
    }
}

[Serializable]
public class EnemyData : EntityData
{
    [Header("Core Stats")]
    public int attackPower;           // Base attack power for intents
    public int defensePower;          // Optional, if you have defensive actions

    [Header("Intent System")]
    public EnemyIntent currentIntent; // What the enemy plans to do this turn
    public EnemyAction currentAction; // The full action being performed (includes custom name)
    public IntentIconMapping intentIcons; // Sprite icons for each intent type
    public string intentText;         // Text like "Attack" or "Buff Self"
    public int intentValue;           // How much damage or block that intent will do

    /// <summary>
    /// Gets the sprite icon for the current intent.
    /// </summary>
    public Sprite GetCurrentIntentIcon()
    {
        if (intentIcons == null)
        {
            Debug.LogWarning($"[EnemyData] {enemyName} has no intent icons assigned!");
            return null;
        }
        return intentIcons.GetIconForIntent(currentIntent);
    }

    [Header("Behavior")]
    public List<EnemyAction> actionPattern; // Optional list of possible actions

    [Header("Metadata")]
    public int enemyID;
    public string enemyName;
    public Sprite artwork;                  // Optional portrait or sprite
    public AudioClip attackSFX;             // Optional sound for attack

    [Header("Animator (Optional)")]
    public RuntimeAnimatorController animatorController; // If set, animator-driven states are used

    [Header("Sprite Animations (Lightweight alternative to AnimationClips)")]
    public SpriteAnimation idleAnim;
    public SpriteAnimation attackAnim;
    public SpriteAnimation hurtAnim;
    public SpriteAnimation deathAnim;

    [Header("Visual Adjustments")]
    public Vector3 positionOffset = Vector3.zero;
    public Vector3 scaleOffset = Vector3.one;

    // -------------------------------------------------------
    // Initialization
    // -------------------------------------------------------
    public void Initialize(string name, int maxHealth, int atk, int def)
    {
        enemyName = name;
        attackPower = atk;
        defensePower = def;

        // Call base EntityData initialization
        base.Initialize(name, maxHealth);

        actionPattern = new List<EnemyAction>();
    }

    // -------------------------------------------------------
    // Enemy chooses what to do next - Intelligent AI System
    // -------------------------------------------------------
    public void DecideNextIntent()
    {
        if (actionPattern == null || actionPattern.Count == 0)
        {
            // Default: simple attack
            currentIntent = EnemyIntent.Attack;
            currentAction = new EnemyAction { intent = EnemyIntent.Attack, value = attackPower, customName = "" };
            intentValue = attackPower;
            intentText = "Attack";
            return;
        }

        // Use intelligent AI to decide best move based on current situation
        EnemyAction chosenAction = ChooseStrategicAction();
        currentIntent = chosenAction.intent;
        currentAction = chosenAction; // Store the full action (includes custom name)
        intentValue = chosenAction.value;
        intentText = chosenAction.intent.ToString();
    }

    /// <summary>
    /// Intelligent AI system that chooses the best action based on enemy's current stats and situation.
    /// </summary>
    private EnemyAction ChooseStrategicAction()
    {
        // Calculate health percentage
        float healthPercent = currentHealth / (float)maxHealth;

        // Separate actions by type for strategic selection
        List<EnemyAction> attackActions = new List<EnemyAction>();
        List<EnemyAction> blockActions = new List<EnemyAction>();
        List<EnemyAction> healActions = new List<EnemyAction>();
        List<EnemyAction> buffActions = new List<EnemyAction>();

        foreach (var action in actionPattern)
        {
            switch (action.intent)
            {
                case EnemyIntent.Attack:
                    attackActions.Add(action);
                    break;
                case EnemyIntent.Block:
                    blockActions.Add(action);
                    break;
                case EnemyIntent.Heal:
                    healActions.Add(action);
                    break;
                case EnemyIntent.Buff:
                    buffActions.Add(action);
                    break;
            }
        }

        // Calculate average block value to set "low block" threshold
        int averageBlockValue = 0;
        if (blockActions.Count > 0)
        {
            int totalBlockValue = 0;
            foreach (var blockAction in blockActions)
            {
                totalBlockValue += blockAction.value;
            }
            averageBlockValue = totalBlockValue / blockActions.Count;
        }

        // Define block thresholds based on available block actions
        int lowBlockThreshold = averageBlockValue / 2; // Half of average block is "low"
        int criticalBlockThreshold = Mathf.Max(3, averageBlockValue / 4); // Very low block
        bool hasLowBlock = block > 0 && block <= lowBlockThreshold;
        bool hasCriticalBlock = block > 0 && block <= criticalBlockThreshold;
        bool hasNoBlock = block == 0;
        bool hasGoodBlock = block > lowBlockThreshold;

        // AI Decision Tree based on stats and situation

        // CRITICAL HEALTH (< 20%) - Prioritize survival
        if (healthPercent < 0.2f)
        {
            // First priority: Heal if available
            if (healActions.Count > 0)
            {
                Debug.Log($"[AI] {enemyName} is critical ({healthPercent:P0}) - choosing HEAL");
                return GetRandomAction(healActions);
            }
            // Second priority: Block to survive (even if we have some block)
            if (blockActions.Count > 0 && (hasNoBlock || hasCriticalBlock))
            {
                Debug.Log($"[AI] {enemyName} is critical ({healthPercent:P0}) with low/no block ({block}) - choosing BLOCK");
                return GetRandomAction(blockActions);
            }
        }

        // LOW HEALTH (20% - 50%) - Defensive play
        if (healthPercent < 0.5f)
        {
            // High priority: Heal if available (70% chance)
            if (healActions.Count > 0 && UnityEngine.Random.value < 0.7f)
            {
                Debug.Log($"[AI] {enemyName} is low health ({healthPercent:P0}) - choosing HEAL");
                return GetRandomAction(healActions);
            }

            // Maintain block coverage - refresh if low or none
            if (blockActions.Count > 0 && (hasNoBlock || hasLowBlock))
            {
                // 70% chance to refresh block when vulnerable at low health
                if (UnityEngine.Random.value < 0.7f)
                {
                    Debug.Log($"[AI] {enemyName} is low health ({healthPercent:P0}) with low block ({block}) - refreshing BLOCK");
                    return GetRandomAction(blockActions);
                }
            }
        }

        // BLOCK MAINTENANCE (any health) - Keep defensive coverage
        if (hasNoBlock && blockActions.Count > 0)
        {
            // 50% chance to block when completely unprotected
            if (UnityEngine.Random.value < 0.5f)
            {
                Debug.Log($"[AI] {enemyName} has no block - choosing BLOCK for protection");
                return GetRandomAction(blockActions);
            }
        }
        else if (hasCriticalBlock && blockActions.Count > 0)
        {
            // 40% chance to refresh when block is critically low
            if (UnityEngine.Random.value < 0.4f)
            {
                Debug.Log($"[AI] {enemyName} has critically low block ({block}) - refreshing BLOCK");
                return GetRandomAction(blockActions);
            }
        }
        else if (hasLowBlock && blockActions.Count > 0)
        {
            // 25% chance to maintain when block is just low
            if (UnityEngine.Random.value < 0.25f)
            {
                Debug.Log($"[AI] {enemyName} has low block ({block}) - maintaining BLOCK");
                return GetRandomAction(blockActions);
            }
        }

        // FULL HEALTH with GOOD BLOCK - Can afford to buff
        if (healthPercent > 0.8f && hasGoodBlock && buffActions.Count > 0)
        {
            // 30% chance to buff when safe
            if (UnityEngine.Random.value < 0.3f)
            {
                Debug.Log($"[AI] {enemyName} is healthy ({healthPercent:P0}) with good block ({block}) - choosing BUFF");
                return GetRandomAction(buffActions);
            }
        }

        // DEFAULT - Attack (aggressive AI)
        if (attackActions.Count > 0)
        {
            Debug.Log($"[AI] {enemyName} choosing ATTACK (HP: {healthPercent:P0}, Block: {block})");
            return GetRandomAction(attackActions);
        }

        // FALLBACK - Return any random action if attack not available
        Debug.LogWarning($"[AI] {enemyName} has no attack actions - picking random");
        return actionPattern[UnityEngine.Random.Range(0, actionPattern.Count)];
    }

    /// <summary>
    /// Helper method to get a random action from a list
    /// </summary>
    private EnemyAction GetRandomAction(List<EnemyAction> actions)
    {
        if (actions == null || actions.Count == 0)
        {
            Debug.LogError("[AI] GetRandomAction called with empty list!");
            return actionPattern[0]; // Fallback
        }
        return actions[UnityEngine.Random.Range(0, actions.Count)];
    }

    // -------------------------------------------------------
    // Execute current intent
    // -------------------------------------------------------
    public void ExecuteIntent(PlayerData player)
    {
        if (player == null) return;

        switch (currentIntent)
        {
            case EnemyIntent.Attack:
                player.TakeDamage(intentValue);
                break;

            case EnemyIntent.Block:
                GainBlock(intentValue);  // Now calls inherited method
                break;

            case EnemyIntent.Heal:
                Heal(intentValue);  // Now calls inherited method
                break;

            case EnemyIntent.Buff:
                ApplyStatus("Strength", intentValue);  // Now calls inherited method
                break;
        }
    }

    public bool IsAlive() => isAlive;  // Now uses inherited field
}

using Entities.Enemies.Helpers;
using Entities.Enemies.Data;
using Entities.Players.Data;
using GameItems;

namespace Entities.Enemies.Manager
{
    using System.Collections.Generic;
    using UnityEngine;

    public class EnemyManager : MonoBehaviour
    {
        [Header("Data")]
        public List<EnemyData> enemies = new();

        [Header("Intent Icons")]
        [Tooltip("Optional: Global intent icon config. If set, all enemies without their own icons will use this.")]
        public IntentIconConfig globalIntentIcons;

        [Header("Rendering")]
        [Tooltip("Parent container where enemy GameObjects (SpriteRenderer + Animator) will be spawned in world space.")]
        public Transform uiContainer; // now a Transform, not a RectTransform
        [Tooltip("Prefab for the enemy health bar UI (must have EnemyHealth component).")]
        [SerializeField] private GameObject healthBarPrefab;

        [Header("Layout (Line-up)")]
        [Tooltip("Horizontal spacing between enemies in world units.")]
        [SerializeField] private float horizontalSpacing = 2f;
        [Tooltip("Fixed Y offset for the line-up (local to container).")]
        [SerializeField] private float yOffset;
        [Tooltip("Center the lineup around X=0. If false, lineup starts at X=0 and grows positive.")]
        [SerializeField] private bool centerAlign = true;
        [Tooltip("Automatically layout enemies after (re)building.")]
        [SerializeField] private bool autoLayoutOnBuild = true;

        [Header("Health Bar Settings")]
        [Tooltip("Local position offset for health bar relative to enemy.")]
        [SerializeField] private Vector3 healthBarOffset = new Vector3(0f, 0.17f, 0f);

        private readonly List<EnemyRender> _activeRenders = new();

        public void InitializeEnemies(List<EnemyData> enemyList)
        {
            enemies = enemyList;
            BuildEnemyUI();
        }

        private void BuildEnemyUI()
        {
            // Cleanup old
            foreach (var r in _activeRenders)
            {
                if (r != null) Destroy(r.gameObject);
            }
            _activeRenders.Clear();

            if (uiContainer == null)
            {
                Debug.LogWarning("EnemyManager: uiContainer not set. Enemies will not be rendered.");
                return;
            }

            if (healthBarPrefab == null)
            {
                Debug.LogWarning("EnemyManager: healthBarPrefab not set. Health bars will not be created.");
            }

            for (int i = 0; i < enemies.Count; i++)
            {
                var enemy = enemies[i];
                var go = new GameObject(string.IsNullOrEmpty(enemy.enemyName) ? $"Enemy_{i}" : enemy.enemyName,
                    typeof(Animator), typeof(SpriteRenderer), typeof(EnemyRender));

                // Parent under the provided container
                var t = go.transform;
                t.SetParent(uiContainer, false);

                // World-space transform defaults
                t.localPosition = Vector3.zero;
                t.localScale = Vector3.one * 10f;
                t.localRotation = Quaternion.identity;

                var sr = go.GetComponent<SpriteRenderer>();
                sr.sprite = enemy.artwork;
                sr.sortingOrder = i; // order by spawn index (front-to-back or vice versa as needed)

                // Add health bar if prefab is available
                if (healthBarPrefab != null)
                {
                    var healthBarGo = Instantiate(healthBarPrefab, go.transform);
                    var healthComp = healthBarGo.GetComponent<EnemyHealth>();
                    if (healthComp != null)
                    {
                        healthComp.SetLocalPosition(healthBarOffset);
                        // Initial health will be set in EnemyRender.Bind
                    }
                    else
                    {
                        Debug.LogWarning($"EnemyManager: healthBarPrefab for {enemy.enemyName} does not have EnemyHealth component.");
                    }
                }

                var render = go.GetComponent<EnemyRender>();
                render.Bind(enemy);

                _activeRenders.Add(render);
            }

            if (autoLayoutOnBuild)
                ApplyLineUpLayout();
        }

        private void ApplyLineUpLayout()
        {
            int count = _activeRenders.Count;
            if (count == 0) return;

            float startX = centerAlign ? -((count - 1) * horizontalSpacing) * 0.5f : 0f;

            for (int i = 0; i < count; i++)
            {
                var r = _activeRenders[i];
                if (r == null) continue;

                var t = r.transform;
                t.localPosition = new Vector3(startX + i * horizontalSpacing, yOffset, 0f);
            }
        }

        // Roll/decide next intents for all alive enemies (called at round start)
        public void RollNextIntents()
        {
            for (int i = 0; i < enemies.Count; i++)
            {
                var enemy = enemies[i];
                if (!enemy.isAlive) continue;

                // DON'T reset block here - let it persist through the player's turn

                // Auto-assign global intent icons if enemy doesn't have its own
                if (enemy.intentIcons == null && globalIntentIcons != null)
                {
                    enemy.intentIcons = globalIntentIcons.ToMapping();
                }

                enemy.DecideNextIntent();

                // Ensure idle is playing so player sees them idling before attack
                var r = GetRenderFor(enemy);
                if (r != null)
                {
                    r.PlayIdle();
                    r.UpdateIntentIcon(); // Show the intent icon
                    r.UpdateHealth(); // Keep existing block visible
                }
            }
        }


        public void RemoveDeadEnemies()
        {
            for (int i = enemies.Count - 1; i >= 0; i--)
            {
                if (!enemies[i].isAlive)
                {
                    enemies.RemoveAt(i);

                    if (_activeRenders.Count > i)
                        _activeRenders.RemoveAt(i);
                }
            }

            // re-layout remaining enemies
            // ApplyLineUpLayout();
        }

        // Enemies execute their previously decided intents with delays (turn-based feel)
        public System.Collections.IEnumerator ExecuteEnemyTurnSequence(PlayerData player)
        {

            for (int i = 0; i < enemies.Count; i++)
            {
                var enemy = enemies[i];
                if (!enemy.isAlive) continue;

                Debug.Log($"[EnemyManager] {enemy.enemyName} is taking their turn...");

                // Get the render for animation
                var r = GetRenderFor(enemy);

                // Show move name popup BEFORE executing the move
                if (r != null)
                {
                    string moveName = r.GetMoveNameForIntent(enemy.currentIntent);

                    // Show popup and wait for it to be visible
                    r.ShowMoveNamePopup(moveName);
                    yield return new WaitForSeconds(0.3f); // Brief pause to let player see the move name
                }

                // Play intent animation based on type
                if (enemy.currentIntent == EnemyIntent.Attack)
                {
                    if (r != null) r.PlayAttack();

                    // Wait for attack animation to play out
                    yield return new WaitForSeconds(0.5f);
                }
                else if (enemy.currentIntent == EnemyIntent.Block)
                {
                    if (r != null) r.PlayIdle(); // Or a defend animation if you have one
                    yield return new WaitForSeconds(0.3f);
                }
                else
                {
                    // Default for Heal/Buff/other intents
                    if (r != null) r.PlayIdle();
                    yield return new WaitForSeconds(0.3f);
                }

                // Execute the intent (apply damage, gain block, etc.)
                enemy.ExecuteIntent(player);

                // Update the enemy's health display to show new shield/health values
                if (r != null)
                {
                    r.UpdateHealth();
                }

                // Brief pause to show the effect
                yield return new WaitForSeconds(0.4f);

                // Return to idle after action
                if (r != null) r.PlayIdle();

                // Delay before next enemy acts
                yield return new WaitForSeconds(0.6f);
            }

            Debug.Log("[EnemyManager] All enemies have completed their turns.");
        }

        // Legacy synchronous method - kept for backwards compatibility but deprecated
        [System.Obsolete("Use ExecuteEnemyTurnSequence coroutine instead for turn-based delays")]
        public void ExecuteEnemyTurn(ref PlayerData player)
        {
            for (int i = 0; i < enemies.Count; i++)
            {
                var enemy = enemies[i];
                if (!enemy.isAlive) continue;

                // Play attack animation right before executing if intent is attack
                if (enemy.currentIntent == EnemyIntent.Attack)
                {
                    var r = GetRenderFor(enemy);
                    if (r != null) r.PlayAttack();
                }

                enemy.ExecuteIntent(player);
            }
        }

        // Call after enemy takes damage to update health display
        public void UpdateEnemyHealth(EnemyData enemy)
        {
            var render = GetRenderFor(enemy);
            if (render != null)
            {
                render.UpdateHealth();

                // Play hurt animation if still alive
                if (enemy.isAlive)
                {
                    render.PlayHurt();
                }
                else
                {
                    render.PlayDeath();

                    RemoveDeadEnemies(); // remove from manager list
                }
            }
            FindFirstObjectByType<RoundManager>()?.CheckImmediateEndConditions();
        }

        // Age enemy block and reset old block (1+ turns old)
        // This allows block gained THIS turn to persist through the next round
        public void ResetAllEnemyBlock()
        {
            foreach (var enemy in enemies)
            {
                if (!enemy.isAlive) continue;

                // Increment block age
                if (enemy.block > 0)
                {
                    enemy.blockAge++;

                    // Only reset block that's 1 or more turns old
                    if (enemy.blockAge >= 2)
                    {
                        Debug.Log($"[EnemyManager] {enemy.enemyName} block expired (age {enemy.blockAge}): {enemy.block} → 0");
                        enemy.block = 0;
                        enemy.blockAge = 0;

                        var r = GetRenderFor(enemy);
                        if (r != null)
                            r.UpdateHealth();
                    }
                    else
                    {
                        Debug.Log($"[EnemyManager] {enemy.enemyName} block persists (age {enemy.blockAge}): {enemy.block} block");
                    }
                }
            }
        }

        private EnemyRender GetRenderFor(EnemyData enemy)
        {
            // Renders are built in the same order as enemies
            int idx = enemies.IndexOf(enemy);
            if (idx >= 0 && idx < _activeRenders.Count)
                return _activeRenders[idx];
            return null;
        }

        public bool AllEnemiesDefeated()
        {
            foreach (var e in enemies)
                if (e.isAlive) return false;
            return true;
        }
    }
}

using Entities.Enemies.Helpers;
using Entities.Enemies.Data;
using Entities.Players.Data;
using GameItems;

namespace Entities.Enemies.Manager
{
    using System.Collections.Generic;
    using UnityEngine;

    public class EnemyManager : MonoBehaviour
    {
        [Header("Data")]
        public List<EnemyData> enemies = new();

        [Header("Intent Icons")]
        [Tooltip("Optional: Global intent icon config. If set, all enemies without their own icons will use this.")]
        public IntentIconConfig globalIntentIcons;

        [Header("Rendering")]
        [Tooltip("Parent container where enemy GameObjects (SpriteRenderer + Animator) will be spawned in world space.")]
        public Transform uiContainer; // now a Transform, not a RectTransform
        [Tooltip("Prefab for the enemy health bar UI (must have EnemyHealth component).")]
        [SerializeField] private GameObject healthBarPrefab;

        [Header("Layout (Line-up)")]
        [Tooltip("Horizontal spacing between enemies in world units.")]
        [SerializeField] private float horizontalSpacing = 2f;
        [Tooltip("Fixed Y offset for the line-up (local to container).")]
        [SerializeField] private float yOffset;
        [Tooltip("Center the lineup around X=0. If false, lineup starts at X=0 and grows positive.")]
        [SerializeField] private bool centerAlign = true;
        [Tooltip("Automatically layout enemies after (re)building.")]
        [SerializeField] private bool autoLayoutOnBuild = true;

        [Header("Health Bar Settings")]
        [Tooltip("Local position offset for health bar relative to enemy.")]
        [SerializeField] private Vector3 healthBarOffset = new Vector3(0f, 0.17f, 0f);

        private readonly List<EnemyRender> _activeRenders = new();

        public void InitializeEnemies(List<EnemyData> enemyList)
        {
            enemies = enemyList;
            BuildEnemyUI();
        }

        private void BuildEnemyUI()
        {
            // Cleanup old
            foreach (var r in _activeRenders)
            {
                if (r != null) Destroy(r.gameObject);
            }
            _activeRenders.Clear();

            if (uiContainer == null)
            {
                Debug.LogWarning("EnemyManager: uiContainer not set. Enemies will not be rendered.");
                return;
            }

            if (healthBarPrefab == null)
            {
                Debug.LogWarning("EnemyManager: healthBarPrefab not set. Health bars will not be created.");
            }

            for (int i = 0; i < enemies.Count; i++)
            {
                var enemy = enemies[i];
                var go = new GameObject(string.IsNullOrEmpty(enemy.enemyName) ? $"Enemy_{i}" : enemy.enemyName,
                    typeof(Animator), typeof(SpriteRenderer), typeof(EnemyRender));

                // Parent under the provided container
                var t = go.transform;
                t.SetParent(uiContainer, false);

                // World-space transform defaults
                t.localPosition = Vector3.zero;
                t.localScale = Vector3.one * 10f;
                t.localRotation = Quaternion.identity;

                var sr = go.GetComponent<SpriteRenderer>();
                sr.sprite = enemy.artwork;
                sr.sortingOrder = i; // order by spawn index (front-to-back or vice versa as needed)

                // Add health bar if prefab is available
                if (healthBarPrefab != null)
                {
                    var healthBarGo = Instantiate(healthBarPrefab, go.transform);
                    var healthComp = healthBarGo.GetComponent<EnemyHealth>();
                    if (healthComp != null)
                    {
                        healthComp.SetLocalPosition(healthBarOffset);
                        // Initial health will be set in EnemyRender.Bind
                    }
                    else
                    {
                        Debug.LogWarning($"EnemyManager: healthBarPrefab for {enemy.enemyName} does not have EnemyHealth component.");
                    }
                }

                var render = go.GetComponent<EnemyRender>();
                render.Bind(enemy);

                _activeRenders.Add(render);
            }

            if (autoLayoutOnBuild)
                ApplyLineUpLayout();
        }

        private void ApplyLineUpLayout()
        {
            int count = _activeRenders.Count;
            if (count == 0) return;

            float startX = centerAlign ? -((count - 1) * horizontalSpacing) * 0.5f : 0f;

            for (int i = 0; i < count; i++)
            {
                var r = _activeRenders[i];
                if (r == null) continue;

                var t = r.transform;
                t.localPosition = new Vector3(startX + i * horizontalSpacing, yOffset, 0f);
            }
        }

        // Roll/decide next intents for all alive enemies (called at round start)
        public void RollNextIntents()
        {
            for (int i = 0; i < enemies.Count; i++)
            {
                var enemy = enemies[i];
                if (!enemy.isAlive) continue;

                // DON'T reset block here - let it persist through the player's turn

                // Auto-assign global intent icons if enemy doesn't have its own
                if (enemy.intentIcons == null && globalIntentIcons != null)
                {
                    enemy.intentIcons = globalIntentIcons.ToMapping();
                }

                enemy.DecideNextIntent();

                // Ensure idle is playing so player sees them idling before attack
                var r = GetRenderFor(enemy);
                if (r != null)
                {
                    r.PlayIdle();
                    r.UpdateIntentIcon(); // Show the intent icon
                    r.UpdateHealth(); // Keep existing block visible
                }
            }
        }


        public void RemoveDeadEnemies()
        {
            for (int i = enemies.Count - 1; i >= 0; i--)
            {
                if (!enemies[i].isAlive)
                {
                    enemies.RemoveAt(i);

                    if (_activeRenders.Count > i)
                        _activeRenders.RemoveAt(i);
                }
            }

            // re-layout remaining enemies
            // ApplyLineUpLayout();
        }

        // Enemies execute their previously decided intents with delays (turn-based feel)
        public System.Collections.IEnumerator ExecuteEnemyTurnSequence(PlayerData player)
        {

            for (int i = 0; i < enemies.Count; i++)
            {
                var enemy = enemies[i];
                if (!enemy.isAlive) continue;

                Debug.Log($"[EnemyManager] {enemy.enemyName} is taking their turn...");

                // Get the render for animation
                var r = GetRenderFor(enemy);

                // Show move name popup BEFORE executing the move
                if (r != null)
                {
                    // Use GetMoveNameForAction to support custom names
                    string moveName = r.GetMoveNameForAction(enemy.currentAction);

                    // Show popup and wait for it to be visible
                    r.ShowMoveNamePopup(moveName);
                    yield return new WaitForSeconds(0.3f); // Brief pause to let player see the move name
                }

                // Play intent animation based on type
                if (enemy.currentIntent == EnemyIntent.Attack)
                {
                    if (r != null) r.PlayAttack();

                    // Wait for attack animation to play out
                    yield return new WaitForSeconds(0.5f);
                }
                else if (enemy.currentIntent == EnemyIntent.Block)
                {
                    if (r != null) r.PlayIdle(); // Or a defend animation if you have one
                    yield return new WaitForSeconds(0.3f);
                }
                else
                {
                    // Default for Heal/Buff/other intents
                    if (r != null) r.PlayIdle();
                    yield return new WaitForSeconds(0.3f);
                }

                // Execute the intent (apply damage, gain block, etc.)
                enemy.ExecuteIntent(player);

                // Update the enemy's health display to show new shield/health values
                if (r != null)
                {
                    r.UpdateHealth();
                }

                // Brief pause to show the effect
                yield return new WaitForSeconds(0.4f);

                // Return to idle after action
                if (r != null) r.PlayIdle();

                // Delay before next enemy acts
                yield return new WaitForSeconds(0.6f);
            }

            Debug.Log("[EnemyManager] All enemies have completed their turns.");
        }

        // Legacy synchronous method - kept for backwards compatibility but deprecated
        [System.Obsolete("Use ExecuteEnemyTurnSequence coroutine instead for turn-based delays")]
        public void ExecuteEnemyTurn(ref PlayerData player)
        {
            for (int i = 0; i < enemies.Count; i++)
            {
                var enemy = enemies[i];
                if (!enemy.isAlive) continue;

                // Play attack animation right before executing if intent is attack
                if (enemy.currentIntent == EnemyIntent.Attack)
                {
                    var r = GetRenderFor(enemy);
                    if (r != null) r.PlayAttack();
                }

                enemy.ExecuteIntent(player);
            }
        }

        // Call after enemy takes damage to update health display
        public void UpdateEnemyHealth(EnemyData enemy)
        {
            var render = GetRenderFor(enemy);
            if (render != null)
            {
                render.UpdateHealth();

                // Play hurt animation if still alive
                if (enemy.isAlive)
                {
                    render.PlayHurt();
                }
                else
                {
                    render.PlayDeath();

                    RemoveDeadEnemies(); // remove from manager list
                }
            }
            FindFirstObjectByType<RoundManager>()?.CheckImmediateEndConditions();
        }

        // Age enemy block and reset old block (1+ turns old)
        // This allows block gained THIS turn to persist through the next round
        public void ResetAllEnemyBlock()
        {
            foreach (var enemy in enemies)
            {
                if (!enemy.isAlive) continue;

                // Increment block age
                if (enemy.block > 0)
                {
                    enemy.blockAge++;

                    // Only reset block that's 1 or more turns old
                    if (enemy.blockAge >= 2)
                    {
                        Debug.Log($"[EnemyManager] {enemy.enemyName} block expired (age {enemy.blockAge}): {enemy.block} → 0");
                        enemy.block = 0;
                        enemy.blockAge = 0;

                        var r = GetRenderFor(enemy);
                        if (r != null)
                            r.UpdateHealth();
                    }
                    else
                    {
                        Debug.Log($"[EnemyManager] {enemy.enemyName} block persists (age {enemy.blockAge}): {enemy.block} block");
                    }
                }
            }
        }

        private EnemyRender GetRenderFor(EnemyData enemy)
        {
            // Renders are built in the same order as enemies
            int idx = enemies.IndexOf(enemy);
            if (idx >= 0 && idx < _activeRenders.Count)
                return _activeRenders[idx];
            return null;
        }

        public bool AllEnemiesDefeated()
        {
            foreach (var e in enemies)
                if (e.isAlive) return false;
            return true;
        }
    }
}

using Entities.Enemies.Helpers;
using UnityEngine;
using TMPro;
using DG.Tweening;

[RequireComponent(typeof(Animator))]
[RequireComponent(typeof(SpriteRenderer))]
[RequireComponent(typeof(BoxCollider2D))]
public class EnemyRender : MonoBehaviour
{
    [Header("Runtime")] public EnemyData data;

    [Header("Intent Icon")]
    [Tooltip("Offset from enemy position where intent icon appears")]
    public Vector3 intentIconOffset = new Vector3(0f, 0.23f, 0f);
    [Tooltip("Size of the intent icon sprite")]
    public float intentIconSize = 0.04f;
    [Tooltip("Sorting layer for intent icon")]
    public string intentIconSortingLayer = "Default";
    [Tooltip("Sorting order offset from enemy sprite")]
    public int intentIconSortingOrderOffset = 10;

    [Header("Intent Value Text")]
    [Tooltip("Offset from icon where value text appears")]
    public Vector3 intentValueOffset = new Vector3(0.5f, -0.3f, 0f);
    [Tooltip("Font size for intent value")]
    public float intentValueFontSize = 10f;
    [Tooltip("Color for intent value text")]
    public Color intentValueColor = Color.white;

    [Header("Move Name Popup")]
    [Tooltip("Offset from enemy position where move name appears")]
    public Vector3 moveNameOffset = new Vector3(0f, -0.11f, 0f);
    [Tooltip("Font size for move name")]
    public float moveNameFontSize = 2f;
    [Tooltip("Color for move name text")]
    public Color moveNameColor = Color.yellow;
    [Tooltip("Duration of move name popup animation")]
    public float moveNameDuration = 1.5f;
    [Tooltip("How far the text moves up during animation")]
    public float moveNameFloatDistance = -0.04f;

    [Header("Animator States (Controller-driven)")]
    public string idleState = "Idle";

    public string attackState = "Attack";
    public string hurtState = "Hurt";
    public string deathState = "Death";
    public int animatorLayer;
    public float crossFadeDuration = 0.08f;

    private SpriteRenderer _sprite;
    private SpriteRenderer _intentIconSprite;
    private GameObject _intentIconObject;
    private TMP_Text _intentValueText;
    private GameObject _intentValueObject;
    private EnemyHealth _health;
    private BoxCollider2D _hitboxCollider;

    private TMP_Text _moveNameText;
    private GameObject _moveNameObject;

    // Manual sprite animation state
    private SpriteAnimation _currentAnimation;
    private float _frameTimer;
    private int _currentFrame;
    private bool _isAnimationPlaying;

    private void Awake()
    {
        _hitboxCollider = GetComponent<BoxCollider2D>();
        _sprite = GetComponent<SpriteRenderer>();

        // Create intent icon GameObject as child
        _intentIconObject = new GameObject("IntentIcon");
        _intentIconObject.transform.SetParent(transform);
        _intentIconObject.transform.localPosition = intentIconOffset;
        _intentIconObject.transform.localScale = Vector3.one * intentIconSize;

        // Add SpriteRenderer for intent icon
        _intentIconSprite = _intentIconObject.AddComponent<SpriteRenderer>();
        _intentIconSprite.sortingLayerName = intentIconSortingLayer;
        _intentIconSprite.sortingOrder = _sprite.sortingOrder + intentIconSortingOrderOffset;
        _intentIconSprite.enabled = false; // Hidden by default

        // Create intent value text as child of icon
        _intentValueObject = new GameObject("IntentValueText");
        _intentValueObject.transform.SetParent(_intentIconObject.transform);
        _intentValueObject.transform.localPosition = intentValueOffset;
        _intentValueObject.transform.localScale = Vector3.one; // Counter parent scale

        // Add TextMeshPro for value display
        _intentValueText = _intentValueObject.AddComponent<TextMeshPro>();
        _intentValueText.fontSize = intentValueFontSize;
        _intentValueText.color = intentValueColor;
        _intentValueText.alignment = TextAlignmentOptions.Center;
        _intentValueText.enabled = false; // Hidden by default

        // Set sorting for text
        var textRenderer = _intentValueText.GetComponent<MeshRenderer>();
        if (textRenderer != null)
        {
            textRenderer.sortingLayerID = _intentIconSprite.sortingLayerID;
            textRenderer.sortingOrder = _intentIconSprite.sortingOrder + 1;
        }

        // Create move name popup text as child
        _moveNameObject = new GameObject("MoveNameText");
        _moveNameObject.transform.SetParent(transform);
        _moveNameObject.transform.localPosition = moveNameOffset;
        _moveNameObject.transform.localScale = Vector3.one * 0.2f;

        // Add TextMeshPro for move name display
        _moveNameText = _moveNameObject.AddComponent<TextMeshPro>();
        _moveNameText.fontSize = moveNameFontSize;
        _moveNameText.color = moveNameColor;
        _moveNameText.alignment = TextAlignmentOptions.Center;
        _moveNameText.fontStyle = FontStyles.Bold;
        _moveNameText.enabled = false; // Hidden by default

        // Set sorting for move name text
        var moveNameRenderer = _moveNameText.GetComponent<MeshRenderer>();
        if (moveNameRenderer != null)
        {
            moveNameRenderer.sortingLayerName = intentIconSortingLayer;
            moveNameRenderer.sortingOrder = _sprite.sortingOrder + 20; // Above everything else
        }
    }

    private void Update()
    {
        if (!_isAnimationPlaying || _currentAnimation == null || _currentAnimation.frames.Count == 0)
            return;

        _frameTimer += Time.deltaTime;
        float frameDuration = 1f / _currentAnimation.frameRate;

        if (_frameTimer >= frameDuration)
        {
            _frameTimer -= frameDuration;
            _currentFrame++;

            if (_currentFrame >= _currentAnimation.frames.Count)
            {
                if (_currentAnimation.loop)
                {
                    _currentFrame = 0;
                }
                else
                {
                    _isAnimationPlaying = false;
                    PlayIdle(); // Revert to idle when non-looping animation finishes
                    return;
                }
            }

            _sprite.sprite = _currentAnimation.frames[_currentFrame];
        }
        data.worldPosition = transform.position;
    }


    public void Bind(EnemyData enemyData)
    {
        data = enemyData;
        data.worldPosition = transform.position;
        data.isPlayer = false;

        // Set default sprite artwork
        if (_sprite != null)
        {
            _sprite.sprite = data != null ? data.artwork : null;
            _sprite.enabled = _sprite.sprite != null;
        }

        // Apply visual adjustments from EnemyData
        if (data != null)
        {
            // Apply position offset
            transform.localPosition += data.positionOffset;

            // Apply scale offset
            transform.localScale = Vector3.Scale(transform.localScale, data.scaleOffset);
        }

        _health = GetComponentInChildren<EnemyHealth>();

        _hitboxCollider.offset = new Vector2(0f, 0.05f);
        _hitboxCollider.size = new Vector2(0.3f, 0.3f);

        // Update health display
        UpdateHealth();

        // Update intent icon
        UpdateIntentIcon();

        PlayIdle();
    }

    /// <summary>
    /// Updates the intent icon based on the current enemy data intent.
    /// Call this after rolling intents or when intent changes.
    /// </summary>
    public void UpdateIntentIcon()
    {
        if (data == null || _intentIconSprite == null)
        {
            HideIntentIcon();
            return;
        }

        Sprite intentSprite = data.GetCurrentIntentIcon();

        if (intentSprite != null)
        {
            _intentIconSprite.sprite = intentSprite;
            _intentIconSprite.enabled = true;

            // Show intent value if > 0
            if (_intentValueText != null && data.intentValue > 0)
            {
                _intentValueText.text = data.intentValue.ToString();
                _intentValueText.enabled = true;
            }
            else if (_intentValueText != null)
            {
                _intentValueText.enabled = false;
            }
        }
        else
        {
            HideIntentIcon();
            Debug.LogWarning($"[EnemyRender] No intent icon for {data.enemyName} with intent {data.currentIntent}");
        }
    }

    /// <summary>
    /// Hides the intent icon (e.g., when enemy is dead or has no intent).
    /// </summary>
    public void HideIntentIcon()
    {
        if (_intentIconSprite != null)
        {
            _intentIconSprite.enabled = false;
        }

        if (_intentValueText != null)
        {
            _intentValueText.enabled = false;
        }
    }

    /// <summary>
    /// Shows the intent icon with the given sprite.
    /// </summary>
    public void ShowIntentIcon(Sprite icon)
    {
        if (_intentIconSprite != null && icon != null)
        {
            _intentIconSprite.sprite = icon;
            _intentIconSprite.enabled = true;
        }
    }

    /// <summary>
    /// Shows a popup text with the move name that floats up and fades out.
    /// Call this immediately before the enemy executes their action.
    /// </summary>
    /// <param name="moveName">The name of the move to display</param>
    /// <param name="onComplete">Optional callback when animation completes</param>
    public void ShowMoveNamePopup(string moveName, System.Action onComplete = null)
    {
        if (_moveNameText == null || string.IsNullOrEmpty(moveName))
        {
            onComplete?.Invoke();
            return;
        }

        // Set the move name text
        _moveNameText.text = moveName.ToUpper();
        _moveNameText.enabled = true;

        // Reset position and alpha
        _moveNameObject.transform.localPosition = moveNameOffset;
        _moveNameText.alpha = 1f;

        // Kill any existing tweens on this object
        DG.Tweening.DOTween.Kill(_moveNameObject.transform);
        DG.Tweening.DOTween.Kill(_moveNameText);

        // Create animation sequence
        DG.Tweening.Sequence moveSequence = DG.Tweening.DOTween.Sequence();

        // Float up
        moveSequence.Append(_moveNameObject.transform
            .DOLocalMoveY(moveNameOffset.y + moveNameFloatDistance, moveNameDuration)
            .SetEase(DG.Tweening.Ease.OutCubic));

        // Fade out in the last half of the animation
        moveSequence.Join(_moveNameText
            .DOFade(0f, moveNameDuration * 0.5f)
            .SetDelay(moveNameDuration * 0.5f));

        // Hide and callback when complete
        moveSequence.OnComplete(() =>
        {
            if (_moveNameText != null)
                _moveNameText.enabled = false;
            onComplete?.Invoke();
        });
    }

    /// <summary>
    /// Gets the move name based on the current intent.
    /// </summary>
    public string GetMoveNameForIntent(EnemyIntent intent)
    {
        return intent switch
        {
            EnemyIntent.Attack => "Attack",
            EnemyIntent.Block => "Defend",
            EnemyIntent.Heal => "Heal",
            EnemyIntent.Buff => "Buff",
            _ => "???"
        };
    }

    public void UpdateHealth()
    {
        if (_health != null && data != null)
        {
            _health.SetHealth(data.currentHealth, data.maxHealth);
            _health.SetShield(data.block);
        }
    }

    public void PlayIdle()
    {
        if (data != null && data.idleAnim != null)
            PlayAnimation(data.idleAnim);
    }

    public void PlayAttack()
    {
        if (data != null && data.attackAnim != null)
            PlayAnimation(data.attackAnim);
    }

    public void PlayHurt()
    {
        if (data != null && data.hurtAnim != null)
            PlayAnimation(data.hurtAnim);
    }

    public void PlayDeath()
    {
        // Hide intent icon on death
        HideIntentIcon();

        // if (data != null && data.deathAnim != null)
        // {
        //     PlayAnimation(data.deathAnim);
        // }
        // else
        // {
        //     // Hide on death if no clip
        //     if (_sprite != null) _sprite.enabled = false;
        // }

        // run death through coroutine
        if (data != null && data.deathAnim != null)
        {
            StartCoroutine(PlayDeathThenDestroy());
        }
        else
        {
            Destroy(gameObject);
        }
    }

    private void PlayAnimation(SpriteAnimation anim)
    {
        if (anim == null || anim.frames.Count == 0)
        {
            _isAnimationPlaying = false;
            return;
        }

        _currentAnimation = anim;
        _isAnimationPlaying = true;
        _currentFrame = 0;
        _frameTimer = 0f;

        // Set the first frame immediately
        _sprite.sprite = _currentAnimation.frames[0];
    }


    private System.Collections.IEnumerator PlayDeathThenDestroy()
    {
        // play the manual sprite animation
        PlayAnimation(data.deathAnim);

        // wait for death animation duration
        float duration = data.deathAnim.Duration;
        if (duration <= 0) duration = 0.5f;

        yield return new WaitForSeconds(duration);

        Destroy(gameObject);
    }

    // Remove all the old Playables and Animator-related methods
    // ... (CrossFadeState, HasState, PlayClip, ReturnToIdleAfterClip, EnsureGraph, StopGraph)
}

using Entities.Enemies.Helpers;
using UnityEngine;
using TMPro;
using DG.Tweening;

[RequireComponent(typeof(Animator))]
[RequireComponent(typeof(SpriteRenderer))]
[RequireComponent(typeof(BoxCollider2D))]
public class EnemyRender : MonoBehaviour
{
    [Header("Runtime")] public EnemyData data;

    [Header("Intent Icon")]
    [Tooltip("Offset from enemy position where intent icon appears")]
    public Vector3 intentIconOffset = new Vector3(0f, 0.23f, 0f);
    [Tooltip("Size of the intent icon sprite")]
    public float intentIconSize = 0.04f;
    [Tooltip("Sorting layer for intent icon")]
    public string intentIconSortingLayer = "Default";
    [Tooltip("Sorting order offset from enemy sprite")]
    public int intentIconSortingOrderOffset = 10;

    [Header("Intent Value Text")]
    [Tooltip("Offset from icon where value text appears")]
    public Vector3 intentValueOffset = new Vector3(0.5f, -0.3f, 0f);
    [Tooltip("Font size for intent value")]
    public float intentValueFontSize = 10f;
    [Tooltip("Color for intent value text")]
    public Color intentValueColor = Color.white;

    [Header("Move Name Popup")]
    [Tooltip("Offset from enemy position where move name appears")]
    public Vector3 moveNameOffset = new Vector3(0f, -0.11f, 0f);
    [Tooltip("Font size for move name")]
    public float moveNameFontSize = 2f;
    [Tooltip("Color for move name text")]
    public Color moveNameColor = Color.yellow;
    [Tooltip("Duration of move name popup animation")]
    public float moveNameDuration = 1.5f;
    [Tooltip("How far the text moves up during animation")]
    public float moveNameFloatDistance = -0.04f;

    [Header("Animator States (Controller-driven)")]
    public string idleState = "Idle";

    public string attackState = "Attack";
    public string hurtState = "Hurt";
    public string deathState = "Death";
    public int animatorLayer;
    public float crossFadeDuration = 0.08f;

    private SpriteRenderer _sprite;
    private SpriteRenderer _intentIconSprite;
    private GameObject _intentIconObject;
    private TMP_Text _intentValueText;
    private GameObject _intentValueObject;
    private EnemyHealth _health;
    private BoxCollider2D _hitboxCollider;

    private TMP_Text _moveNameText;
    private GameObject _moveNameObject;

    // Manual sprite animation state
    private SpriteAnimation _currentAnimation;
    private float _frameTimer;
    private int _currentFrame;
    private bool _isAnimationPlaying;

    private void Awake()
    {
        _hitboxCollider = GetComponent<BoxCollider2D>();
        _sprite = GetComponent<SpriteRenderer>();

        // Create intent icon GameObject as child
        _intentIconObject = new GameObject("IntentIcon");
        _intentIconObject.transform.SetParent(transform);
        _intentIconObject.transform.localPosition = intentIconOffset;
        _intentIconObject.transform.localScale = Vector3.one * intentIconSize;

        // Add SpriteRenderer for intent icon
        _intentIconSprite = _intentIconObject.AddComponent<SpriteRenderer>();
        _intentIconSprite.sortingLayerName = intentIconSortingLayer;
        _intentIconSprite.sortingOrder = _sprite.sortingOrder + intentIconSortingOrderOffset;
        _intentIconSprite.enabled = false; // Hidden by default

        // Create intent value text as child of icon
        _intentValueObject = new GameObject("IntentValueText");
        _intentValueObject.transform.SetParent(_intentIconObject.transform);
        _intentValueObject.transform.localPosition = intentValueOffset;
        _intentValueObject.transform.localScale = Vector3.one; // Counter parent scale

        // Add TextMeshPro for value display
        _intentValueText = _intentValueObject.AddComponent<TextMeshPro>();
        _intentValueText.fontSize = intentValueFontSize;
        _intentValueText.color = intentValueColor;
        _intentValueText.alignment = TextAlignmentOptions.Center;
        _intentValueText.enabled = false; // Hidden by default

        // Set sorting for text
        var textRenderer = _intentValueText.GetComponent<MeshRenderer>();
        if (textRenderer != null)
        {
            textRenderer.sortingLayerID = _intentIconSprite.sortingLayerID;
            textRenderer.sortingOrder = _intentIconSprite.sortingOrder + 1;
        }

        // Create move name popup text as child
        _moveNameObject = new GameObject("MoveNameText");
        _moveNameObject.transform.SetParent(transform);
        _moveNameObject.transform.localPosition = moveNameOffset;
        _moveNameObject.transform.localScale = Vector3.one * 0.2f;

        // Add TextMeshPro for move name display
        _moveNameText = _moveNameObject.AddComponent<TextMeshPro>();
        _moveNameText.fontSize = moveNameFontSize;
        _moveNameText.color = moveNameColor;
        _moveNameText.alignment = TextAlignmentOptions.Center;
        _moveNameText.fontStyle = FontStyles.Bold;
        _moveNameText.enabled = false; // Hidden by default

        // Set sorting for move name text
        var moveNameRenderer = _moveNameText.GetComponent<MeshRenderer>();
        if (moveNameRenderer != null)
        {
            moveNameRenderer.sortingLayerName = intentIconSortingLayer;
            moveNameRenderer.sortingOrder = _sprite.sortingOrder + 20; // Above everything else
        }
    }

    private void Update()
    {
        if (!_isAnimationPlaying || _currentAnimation == null || _currentAnimation.frames.Count == 0)
            return;

        _frameTimer += Time.deltaTime;
        float frameDuration = 1f / _currentAnimation.frameRate;

        if (_frameTimer >= frameDuration)
        {
            _frameTimer -= frameDuration;
            _currentFrame++;

            if (_currentFrame >= _currentAnimation.frames.Count)
            {
                if (_currentAnimation.loop)
                {
                    _currentFrame = 0;
                }
                else
                {
                    _isAnimationPlaying = false;
                    PlayIdle(); // Revert to idle when non-looping animation finishes
                    return;
                }
            }

            _sprite.sprite = _currentAnimation.frames[_currentFrame];
        }
        data.worldPosition = transform.position;
    }


    public void Bind(EnemyData enemyData)
    {
        data = enemyData;
        data.worldPosition = transform.position;
        data.isPlayer = false;

        // Set default sprite artwork
        if (_sprite != null)
        {
            _sprite.sprite = data != null ? data.artwork : null;
            _sprite.enabled = _sprite.sprite != null;
        }

        // Apply visual adjustments from EnemyData
        if (data != null)
        {
            // Apply position offset
            transform.localPosition += data.positionOffset;

            // Apply scale offset
            transform.localScale = Vector3.Scale(transform.localScale, data.scaleOffset);
        }

        _health = GetComponentInChildren<EnemyHealth>();

        _hitboxCollider.offset = new Vector2(0f, 0.05f);
        _hitboxCollider.size = new Vector2(0.3f, 0.3f);

        // Update health display
        UpdateHealth();

        // Update intent icon
        UpdateIntentIcon();

        PlayIdle();
    }

    /// <summary>
    /// Updates the intent icon based on the current enemy data intent.
    /// Call this after rolling intents or when intent changes.
    /// </summary>
    public void UpdateIntentIcon()
    {
        if (data == null || _intentIconSprite == null)
        {
            HideIntentIcon();
            return;
        }

        Sprite intentSprite = data.GetCurrentIntentIcon();

        if (intentSprite != null)
        {
            _intentIconSprite.sprite = intentSprite;
            _intentIconSprite.enabled = true;

            // Show intent value if > 0
            if (_intentValueText != null && data.intentValue > 0)
            {
                _intentValueText.text = data.intentValue.ToString();
                _intentValueText.enabled = true;
            }
            else if (_intentValueText != null)
            {
                _intentValueText.enabled = false;
            }
        }
        else
        {
            HideIntentIcon();
            Debug.LogWarning($"[EnemyRender] No intent icon for {data.enemyName} with intent {data.currentIntent}");
        }
    }

    /// <summary>
    /// Hides the intent icon (e.g., when enemy is dead or has no intent).
    /// </summary>
    public void HideIntentIcon()
    {
        if (_intentIconSprite != null)
        {
            _intentIconSprite.enabled = false;
        }

        if (_intentValueText != null)
        {
            _intentValueText.enabled = false;
        }
    }

    /// <summary>
    /// Shows the intent icon with the given sprite.
    /// </summary>
    public void ShowIntentIcon(Sprite icon)
    {
        if (_intentIconSprite != null && icon != null)
        {
            _intentIconSprite.sprite = icon;
            _intentIconSprite.enabled = true;
        }
    }

    /// <summary>
    /// Shows a popup text with the move name that floats up and fades out.
    /// Call this immediately before the enemy executes their action.
    /// </summary>
    /// <param name="moveName">The name of the move to display</param>
    /// <param name="onComplete">Optional callback when animation completes</param>
    public void ShowMoveNamePopup(string moveName, System.Action onComplete = null)
    {
        if (_moveNameText == null || string.IsNullOrEmpty(moveName))
        {
            onComplete?.Invoke();
            return;
        }

        // Set the move name text
        _moveNameText.text = moveName.ToUpper();
        _moveNameText.enabled = true;

        // Reset position and alpha
        _moveNameObject.transform.localPosition = moveNameOffset;
        _moveNameText.alpha = 1f;

        // Kill any existing tweens on this object
        DG.Tweening.DOTween.Kill(_moveNameObject.transform);
        DG.Tweening.DOTween.Kill(_moveNameText);

        // Create animation sequence
        DG.Tweening.Sequence moveSequence = DG.Tweening.DOTween.Sequence();

        // Float up
        moveSequence.Append(_moveNameObject.transform
            .DOLocalMoveY(moveNameOffset.y + moveNameFloatDistance, moveNameDuration)
            .SetEase(DG.Tweening.Ease.OutCubic));

        // Fade out in the last half of the animation
        moveSequence.Join(_moveNameText
            .DOFade(0f, moveNameDuration * 0.5f)
            .SetDelay(moveNameDuration * 0.5f));

        // Hide and callback when complete
        moveSequence.OnComplete(() =>
        {
            if (_moveNameText != null)
                _moveNameText.enabled = false;
            onComplete?.Invoke();
        });
    }

    /// <summary>
    /// Gets the move name for the given action.
    /// Returns custom name if set, otherwise returns default name based on intent.
    /// </summary>
    public string GetMoveNameForAction(EnemyAction action)
    {
        // Check if custom name is set
        if (!string.IsNullOrEmpty(action.customName))
        {
            return action.customName;
        }

        // Return default name based on intent
        return action.intent switch
        {
            EnemyIntent.Attack => "Attack",
            EnemyIntent.Block => "Defend",
            EnemyIntent.Heal => "Heal",
            EnemyIntent.Buff => "Buff",
            _ => "???"
        };
    }

    /// <summary>
    /// Gets the move name based on the current intent (legacy method).
    /// Use GetMoveNameForAction() for custom name support.
    /// </summary>
    public string GetMoveNameForIntent(EnemyIntent intent)
    {
        return intent switch
        {
            EnemyIntent.Attack => "Attack",
            EnemyIntent.Block => "Defend",
            EnemyIntent.Heal => "Heal",
            EnemyIntent.Buff => "Buff",
            _ => "???"
        };
    }

    public void UpdateHealth()
    {
        if (_health != null && data != null)
        {
            _health.SetHealth(data.currentHealth, data.maxHealth);
            _health.SetShield(data.block);
        }
    }

    public void PlayIdle()
    {
        if (data != null && data.idleAnim != null)
            PlayAnimation(data.idleAnim);
    }

    public void PlayAttack()
    {
        if (data != null && data.attackAnim != null)
            PlayAnimation(data.attackAnim);
    }

    public void PlayHurt()
    {
        if (data != null && data.hurtAnim != null)
            PlayAnimation(data.hurtAnim);
    }

    public void PlayDeath()
    {
        // Hide intent icon on death
        HideIntentIcon();

        // if (data != null && data.deathAnim != null)
        // {
        //     PlayAnimation(data.deathAnim);
        // }
        // else
        // {
        //     // Hide on death if no clip
        //     if (_sprite != null) _sprite.enabled = false;
        // }

        // run death through coroutine
        if (data != null && data.deathAnim != null)
        {
            StartCoroutine(PlayDeathThenDestroy());
        }
        else
        {
            Destroy(gameObject);
        }
    }

    private void PlayAnimation(SpriteAnimation anim)
    {
        if (anim == null || anim.frames.Count == 0)
        {
            _isAnimationPlaying = false;
            return;
        }

        _currentAnimation = anim;
        _isAnimationPlaying = true;
        _currentFrame = 0;
        _frameTimer = 0f;

        // Set the first frame immediately
        _sprite.sprite = _currentAnimation.frames[0];
    }


    private System.Collections.IEnumerator PlayDeathThenDestroy()
    {
        // play the manual sprite animation
        PlayAnimation(data.deathAnim);

        // wait for death animation duration
        float duration = data.deathAnim.Duration;
        if (duration <= 0) duration = 0.5f;

        yield return new WaitForSeconds(duration);

        Destroy(gameObject);
    }

    // Remove all the old Playables and Animator-related methods
    // ... (CrossFadeState, HasState, PlayClip, ReturnToIdleAfterClip, EnsureGraph, StopGraph)
}

using TMPro;
using UnityEngine;
using UnityEngine.UI;

namespace GameItems
{
    /// <summary>
    /// Displays the turn timer UI with a countdown and optional visual feedback.
    /// </summary>
    public class TurnTimerUI : MonoBehaviour
    {
        [Header("References")]
        [Tooltip("Reference to the RoundManager to read timer values")]
        public RoundManager roundManager;

        [Header("UI Elements")]
        [Tooltip("Text component to display the remaining time")]
        public TextMeshProUGUI timerText;

        [Tooltip("Optional fill image to show timer visually")]
        public Image timerFillImage;

        [Header("Visual Settings")]
        [Tooltip("Color when time is plentiful")]
        public Color normalColor = Color.white;

        [Tooltip("Color when time is running low")]
        public Color warningColor = Color.yellow;

        [Tooltip("Color when time is almost out")]
        public Color criticalColor = Color.red;

        [Tooltip("Time threshold for warning color (seconds)")]
        public float warningThreshold = 7f;

        [Tooltip("Time threshold for critical color (seconds)")]
        public float criticalThreshold = 3f;

        private void Start()
        {
            // Auto-find RoundManager if not assigned
            if (roundManager == null)
            {
                roundManager = FindFirstObjectByType<RoundManager>();
            }

            if (roundManager == null)
            {
                Debug.LogError("TurnTimerUI: RoundManager not found!");
                enabled = false;
            }
        }

        private void Update()
        {
            if (roundManager == null || !roundManager.playerTurn || !roundManager.battleActive)
            {
                // Hide timer when not player's turn
                if (timerText != null) timerText.text = "";
                if (timerFillImage != null) timerFillImage.fillAmount = 0f;
                return;
            }

            float timeRemaining = roundManager.currentTurnTime;
            float timeLimit = roundManager.turnTimeLimit;

            // Update text
            if (timerText != null)
            {
                timerText.text = $"{Mathf.CeilToInt(timeRemaining)}s";

                // Update color based on time remaining
                if (timeRemaining <= criticalThreshold)
                {
                    timerText.color = criticalColor;
                }
                else if (timeRemaining <= warningThreshold)
                {
                    timerText.color = warningColor;
                }
                else
                {
                    timerText.color = normalColor;
                }
            }

            // Update fill image
            if (timerFillImage != null && timeLimit > 0)
            {
                timerFillImage.fillAmount = timeRemaining / timeLimit;

                // Update fill color
                if (timeRemaining <= criticalThreshold)
                {
                    timerFillImage.color = criticalColor;
                }
                else if (timeRemaining <= warningThreshold)
                {
                    timerFillImage.color = warningColor;
                }
                else
                {
                    timerFillImage.color = normalColor;
                }
            }
        }
    }
}
